const markMergeabilityUnresolved = `-- name: MarkMergeabilityUnresolved :execrows
UPDATE pull_requests SET mergeability_unresolved_at=clock_timestamp()
WHERE repo_id=$1 AND number=$2 AND generation=$3 AND head_sha=$4 AND state='open' AND build_status='checking'
`

type MarkMergeabilityUnresolvedParams struct {
	RepoID     int64
	Number     int32
	Generation int64
	HeadSha    string
}

// The bounded mergeability check gave up on exactly this observation.
func (q *Queries) MarkMergeabilityUnresolved(ctx context.Context, arg MarkMergeabilityUnresolvedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markMergeabilityUnresolved,
		arg.RepoID,
		arg.Number,
		arg.Generation,
		arg.HeadSha,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

